export const exhibitionPhotoForms = Object.freeze(['photographs', 'light-table', 'photo-carousel', 'photo-ribbon', 'photo-viewer']);
export function exhibitionForm(id) { return exhibitionForms.find(form => form.id === id); }

export function exhibitionFormCandidates(stop) {
  if (stop.kind === 'globe') return ['globe'];
  // A preview is a verified photograph of this exact native component.
  if (stop.componentPreview) return [stop.componentPreview.form];
  const kind = stop.source?.entity?.kind;
  // Research figures need a level surface and generous space for their labels.
  // Keep photographic sculptures exclusive to photographic material.
  if (kind === 'publication' && stop.images?.length) return ['photographs'];
  if (kind === 'gallery' || (stop.kind === 'photograph' && !['project', 'early-project'].includes(kind))) {
    if (stop.images?.length >= 4) return ['photographs', 'light-table', 'photo-carousel', 'photo-ribbon', 'photo-viewer'];
    if (stop.images?.length >= 2) return ['photographs', 'light-table', 'photo-ribbon', 'photo-viewer'];
    if (stop.images?.length) return ['photographs'];
  }
  if (['project', 'early-project'].includes(kind)) return ['screen'];
  return ['folio', 'reading-case', 'hanging-scroll', 'reading-roll'];
}

export function chooseExhibitionForm(stop, view, requested = '') {
  const candidates = exhibitionFormCandidates(stop);
  if (candidates.includes(requested)) return requested;
  // Versioned, source-based seed avoids changes caused by traversal order,
  // browser random state, the date, or an unrelated newly inserted work.
  const seed = JSON.stringify(['carriers-v2', view?.question || view?.title || '', stop.source?.source_id || stop.block?.source_id || stop.id]);
  let hash = 2166136261;
  for (const character of seed) hash = Math.imul(hash ^ character.charCodeAt(0), 16777619) >>> 0;
  hash = (hash ^ (hash >>> 16)) >>> 0;
  return candidates[hash % candidates.length];
}
